package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create request that is missing or blank in any required owner field, before
 * {@link BuildOwner} runs. Publishes the body so the single {@code @RequestBody} binding lives here.
 */
public class RequireOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException {
        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
        List<String> missing = new ArrayList<>();
        require("firstName", request.getFirstName(), missing);
        require("lastName", request.getLastName(), missing);
        require("address", request.getAddress(), missing);
        require("city", request.getCity(), missing);
        require("telephone", request.getTelephone(), missing);
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        validated.set(request);
    }

    private static void require(String name, String value, List<String> missing) {
        if (value == null || value.isBlank()) {
            missing.add(name);
        }
    }
}
===== RequireUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerHouseholdException;

/**
 * Rejects a create request that shares another owner's household, i.e. has the same computed
 * {@code householdId} (last name and postcode, see {@link HouseholdId}). A request with
 * {@code sharesHousehold} true opts out and is created as a declared household member. Requests
 * without a postcode are not grouped into a household. A match rejects 409.
 */
public class RequireUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())
                || request.getPostcode() == null || request.getPostcode().isBlank()) {
            return;
        }
        String household = HouseholdId.of(request.getLastName(), request.getPostcode());
        for (Owner owner : ownerRepository.findAll()) {
            if (household.equals(HouseholdId.of(owner.getLastName(), owner.getPostcode()))) {
                throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
            }
        }
    }
}
===== RequireValidPostcode =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Rejects a create request whose optional {@code postcode} is present but invalid: it
 * must be four digits and, for a city with a known region, within that region's range
 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
 * four-digit value. Absent postcode is accepted (validated only when present).
 */
public class RequireValidPostcode {

    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return;
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidPostcodeException(postcode);
        }
        int[] range = REGION_RANGE.get(CityLocality.of(request.getCity()));
        int value = Integer.parseInt(postcode);
        if (range != null && (value < range[0] || value > range[1])) {
            throw new InvalidPostcodeException(postcode);
        }
    }
}
===== CityLocality =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Derives an owner's locality (canonical region), preferring the postcode: a four-digit
 * postcode within a known region range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
 * wins. When the postcode is absent or in no known range, a fixed city-to-region table
 * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) is used; any other city derives
 * {@code "UNKNOWN"}.
 */
public final class CityLocality {

    private static final Map<String, String> CITY_REGION =
            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});

    private CityLocality() {
    }

    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** Region from the postcode range first, falling back to the city table. */
    public static String of(String city, String postcode) {
        String byPostcode = byPostcode(postcode);
        return byPostcode != null ? byPostcode : of(city);
    }

    private static String byPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> region : REGION_RANGE.entrySet()) {
            int[] range = region.getValue();
            if (value >= range[0] && value <= range[1]) {
                return region.getKey();
            }
        }
        return null;
    }
}
